/**
 * Generates `src/AUTOGENERATED/BasemapGraphQLClass.ts` from mc-models' basemap zod registrations,
 * via the same `@map-colonies/code-generator` the main `npm run generate` uses.
 *
 * This runs as a separate invocation (not folded into `npm run generate`) because
 * `getGraphQLClassMapping()` returns every registered class - layerMetadata's included - and
 * `src/AUTOGENERATED/GraphQLClass.ts` carries manual post-generation patches for that side
 * (duplicate-field workarounds, a couple of corrected field types) that a full regeneration would
 * silently wipe out. Filtering the mapping down to just the basemap classes before generating keeps
 * this run safely isolated to its own output file.
 */
const fs = require('fs');
const classGraphqlDecorator = require('@map-colonies/mc-model-types/Schema/models/common/decorators/graphQL/classGraphql.decorator');
const Generator = require('@map-colonies/code-generator/dist/src/generator').default;
const { Projects, Tasks } = require('@map-colonies/code-generator/dist/src/models/enums');
require('@map-colonies/code-generator/dist/src/graphql/generateGraphQL');

const OUTPUT_PATH = './src/AUTOGENERATED/BasemapGraphQLClass.ts';

// `CatalogResourceSource.layer` references mc-models' `LAYER_RASTER_RECORD_TYPE`, a plain
// same-file CLASS reference (no `importFromPackage`) because code-generator assumes every
// registered class lands in one output file. Since this run only generates the basemap subset,
// `LayerRasterRecord` actually lives in the sibling GraphQLClass.ts - wire the cross-file import
// back in after generation.
const CROSS_FILE_IMPORT = 'import { LayerRasterRecord } from "./GraphQLClass";\n';

// mc-models' generic `Domain` descriptor points at `@map-colonies/mc-model-types`' own re-export of
// `@map-colonies/types`' 3-member `Domain` (RASTER/DEM/_3D) - but this BFF already has its own 4-member
// `Domain` (`../graphql/domain`, RASTER/3D/DEM/VECTOR) registered under the same GraphQL name "Domain"
// and used pervasively across the codebase. Registering a second, different enum under that same name
// would crash type-graphql's schema build, so swap in the BFF's own `Domain` here instead and drop the
// generated file's own (now-redundant) registration of it.
const GENERATED_DOMAIN_IMPORT = ', Domain';
const BFF_DOMAIN_IMPORT = 'import { Domain } from "../graphql/domain";\n';

const BASEMAP_CLASS_NAMES = new Set([
  'Basemap',
  'BasemapThumbnail',
  'BasemapLayer',
  'BasemapLayerSource',
  'CatalogResourceSource',
  'ExternalLayerSource',
  'RasterUniqueness',
  'ExternalLayerDetails',
]);

const realGetMapping = classGraphqlDecorator.getGraphQLClassMapping;
classGraphqlDecorator.getGraphQLClassMapping = () => realGetMapping().filter((graphQLClass) => BASEMAP_CLASS_NAMES.has(graphQLClass.name));

Generator.runOrDie(Projects.RASTER, Tasks.GRAPHQL, OUTPUT_PATH)
  .then(() => {
    let generated = fs.readFileSync(OUTPUT_PATH, 'utf8');
    generated = generated
      .replace(GENERATED_DOMAIN_IMPORT, '')
      .replace(/^const DomainRegister = registerEnumType\(Domain, \{name: "Domain"\}\);\n/m, '');

    const lines = generated.split('\n');
    const lastImportIndex = lines.reduce((last, line, idx) => (line.startsWith('import ') ? idx : last), -1);
    lines.splice(lastImportIndex + 1, 0, CROSS_FILE_IMPORT.trimEnd(), BFF_DOMAIN_IMPORT.trimEnd());
    fs.writeFileSync(OUTPUT_PATH, lines.join('\n'));
  })
  .catch((err) => {
    console.error(err);
    process.exit(1);
  });
